import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import CatalogEditorState from '../CatalogEditorState';
import { uiIcon } from '../../uiIcons';
/** Общее окно отвечает за форму и сохранение. Поля рисует редактор конкретной сущности. */
export default class CatalogEditModal extends Modal {
  oninit(vnode) {
    super.oninit(vnode);
    const {
      definition,
      row,
      data,
      api
    } = this.attrs;
    this.editor = new CatalogEditorState(definition.initial(row), row?.id ?? null, definition.revision(row, data), api);
  }
  className() {
    // Только сущности с карточками используют 620 px. Справочники — 480 px.
    const cards = ['perks', 'items', 'spells'].includes(this.attrs.definition.key);
    return 'RpCatalogEditor' + (cards ? ' RpCatalogEditor--cards' : '');
  }
  title() {
    return m("span", null, m(Icon, {
      name: uiIcon('actions.edit')
    }), " ", this.attrs.row?.name || this.attrs.definition.title);
  }
  wrapper(children) {
    // Flarum 2 не отправляет форму за редактор: задаём настоящий submit явно.
    return m("form", {
      onsubmit: event => {
        event.preventDefault();
        void this.save();
      }
    }, children);
  }
  async save() {
    if (!(await this.editor.save())) return;
    this.hide();
    await this.attrs.onSaved();
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, this.editor.error && m("div", {
      className: "RpCatalog-error",
      role: "alert"
    }, this.editor.error), m("fieldset", {
      className: "RpCatalogEditor-fields",
      disabled: this.editor.saving
    }, this.attrs.definition.editor({
      state: this.editor,
      lookups: this.attrs.data.lookups
    })), m("div", {
      className: "RpEditorActions"
    }, m(Button, {
      type: "submit",
      className: "Button Button--primary",
      icon: uiIcon('actions.save'),
      loading: this.editor.saving,
      disabled: this.editor.uploading
    }, "\u0421\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u044F")));
  }
}
flarum.reg.add('maxcuso-roleplay', 'common/catalog/components/CatalogEditModal', CatalogEditModal);