import app from 'flarum/admin/app';
export default class CreationSettingsApi {
  url() {
    return app.forum.attribute('apiUrl') + '/roleplay/admin/creation';
  }
  async read() {
    return (await app.request({
      method: 'GET',
      url: this.url(),
      errorHandler: () => {}
    })).data;
  }
  async save(data) {
    await app.request({
      method: 'PUT',
      url: this.url(),
      body: {
        revision: data.revision,
        configuration: data.configuration
      },
      errorHandler: () => {}
    });
  }
}
flarum.reg.add('maxcuso-roleplay', 'admin/settings/CreationSettingsApi', CreationSettingsApi);