import { requestMessage } from './CatalogApi';

/** Состояние отделено от разметки: поиск и сохранение проверяются без браузера. */
export default class CatalogListState {
  data = {
    rows: [],
    total: 0,
    page: 1,
    per_page: 30,
    revision: 0,
    lookups: {}
  };
  search = '';
  filters = {};
  page = 1;
  loading = false;
  mutating = false;
  error = '';
  sequence = 0;
  disposed = false;
  constructor(api, redraw) {
    if (redraw === void 0) {
      redraw = () => m.redraw();
    }
    this.api = api;
    this.redraw = redraw;
  }
  async load() {
    if (this.disposed) return;
    const ticket = ++this.sequence;
    this.loading = true;
    this.error = '';
    this.redraw();
    try {
      const data = await this.api.list({
        search: this.search,
        page: this.page,
        ...this.filters
      });
      // Ответ старого поиска не должен заменить результаты нового запроса.
      if (!this.disposed && ticket === this.sequence) this.data = data;
    } catch (error) {
      if (!this.disposed && ticket === this.sequence) this.error = requestMessage(error);
    } finally {
      if (!this.disposed && ticket === this.sequence) {
        this.loading = false;
        this.redraw();
      }
    }
  }
  setSearch(value) {
    this.search = value;
    this.page = 1;
    ++this.sequence;
    this.loading = true;
    clearTimeout(this.searchTimer);
    this.searchTimer = setTimeout(() => void this.load(), 250);
    this.redraw();
  }
  setFilter(key, value) {
    this.filters[key] = value;
    this.page = 1;
    clearTimeout(this.searchTimer);
    void this.load();
  }
  async mutate(action) {
    if (this.disposed || this.mutating || this.loading) return;
    this.mutating = true;
    this.error = '';
    this.redraw();
    try {
      await action();
      await this.load();
    } catch (error) {
      this.error = requestMessage(error);
    } finally {
      this.mutating = false;
      if (!this.disposed) this.redraw();
    }
  }
  dispose() {
    this.disposed = true;
    ++this.sequence;
    clearTimeout(this.searchTimer);
  }
}
flarum.reg.add('maxcuso-roleplay', 'admin/catalog/CatalogListState', CatalogListState);