import SettingsState from '../settings/SettingsState';
/** Узкая форма сохраняет только настройки литературной темы. */
export default class ApplicationSettingsState extends SettingsState {
  constructor(api, redraw) {
    super(() => api.read(), data => api.save(data.revision, data.application), redraw);
  }
}
flarum.reg.add('maxcuso-roleplay', 'admin/application/ApplicationSettingsState', ApplicationSettingsState);