import app from 'flarum/common/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import { requestMessage } from '../../requestError';
import { uiIcon } from '../../uiIcons';
import { FieldLabel } from './FormFields';
/** Файл загружается отдельно; сохранение формы ждёт окончания обработки изображения. */
export default class ImageUpload extends Component {
  error = '';
  async upload(file) {
    const state = this.attrs.state;
    if (state.uploading) return;
    this.error = '';
    if (file.size > 5 * 1024 * 1024) {
      this.error = 'Размер изображения — не более 5 МБ.';
      return;
    }
    state.uploading = true;
    m.redraw();
    try {
      const body = new FormData();
      body.append('image', file);
      const response = await app.request({
        method: 'POST',
        url: app.forum.attribute('apiUrl') + state.imageEndpoint,
        body,
        serialize: data => data,
        errorHandler: () => {}
      });
      state.set('image', response.data.image);
    } catch (error) {
      this.error = requestMessage(error, 'Не удалось загрузить изображение. Попробуй ещё раз.');
    } finally {
      state.uploading = false;
      if (this.input) this.input.value = '';
      m.redraw();
    }
  }
  view() {
    const state = this.attrs.state;
    return m("div", {
      className: "RpImageUpload"
    }, m("label", {
      className: "RpField"
    }, m(FieldLabel, {
      label: "\u0418\u0437\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u0438\u0435",
      field: "image"
    }), m("input", {
      className: "FormControl",
      maxlength: 1000,
      value: state.text('image'),
      disabled: state.uploading,
      oninput: event => state.set('image', event.target.value)
    })), m("input", {
      className: "sr-only",
      type: "file",
      accept: ".svg,.png,.webp,image/svg+xml,image/png,image/webp",
      "aria-label": "\u0424\u0430\u0439\u043B \u0438\u0437\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u0438\u044F \u043F\u0435\u0440\u043A\u0430",
      disabled: state.uploading,
      oncreate: vnode => this.input = vnode.dom,
      onchange: event => {
        const file = event.target.files?.[0];
        if (file) void this.upload(file);
      }
    }), m(Button, {
      className: "Button",
      icon: uiIcon('actions.upload'),
      loading: state.uploading,
      onclick: () => this.input?.click()
    }, "\u0424\u0430\u0439\u043B"), m(Button, {
      className: "Button Button--icon",
      icon: uiIcon('actions.close'),
      "aria-label": "\u0423\u0431\u0440\u0430\u0442\u044C \u0438\u0437\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u0438\u0435",
      disabled: state.uploading || !state.text('image'),
      onclick: () => state.set('image', '')
    }), this.error && m("p", {
      role: "alert"
    }, this.error));
  }
}
flarum.reg.add('maxcuso-roleplay', 'common/catalog/components/ImageUpload', ImageUpload);