import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import { catalogueIcon } from '../../../common/uiIcons';
import { safeImage } from '../../../common/presentation';
/** Поиск и прокрутка для длинных списков. Пустые плашки не создаются. */
export default class MultiPicker extends Component {
  search = '';
  view() {
    const rows = this.attrs.rows.filter(row => row.name.toLocaleLowerCase().includes(this.search.toLocaleLowerCase()));
    return m("div", {
      className: "RpMultiPicker"
    }, m("input", {
      className: "FormControl",
      type: "search",
      "aria-label": "\u041F\u043E\u0438\u0441\u043A \u0432 \u0441\u043F\u0438\u0441\u043A\u0435",
      placeholder: "\u041F\u043E\u0438\u0441\u043A\u2026",
      value: this.search,
      oninput: event => this.search = event.target.value
    }), m("div", {
      className: "RpMultiPicker-options"
    }, rows.map(row => {
      const selected = this.attrs.selected.includes(row.id);
      const blocked = !selected && (this.attrs.blocked ?? []).includes(row.id);
      const image = safeImage(String(row.image ?? ''));
      return m("button", {
        key: row.id,
        type: "button",
        className: 'RpMultiPicker-option' + (selected ? ' is-selected' : ''),
        disabled: blocked,
        "aria-pressed": String(selected),
        onclick: () => this.attrs.onchange(selected ? this.attrs.selected.filter(id => id !== row.id) : [...this.attrs.selected, row.id])
      }, image ? m("img", {
        src: image,
        alt: ""
      }) : m(Icon, {
        name: catalogueIcon(this.attrs.icon?.(row) ?? String(row.icon ?? ''))
      }), m("span", null, this.attrs.label?.(row) ?? row.name));
    })), rows.length === 0 && m("p", {
      className: "helpText"
    }, "\u0417\u0430\u043F\u0438\u0441\u0438 \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u044B"));
  }
}
flarum.reg.add('maxcuso-roleplay', 'admin/catalog/components/MultiPicker', MultiPicker);