import app from 'flarum/admin/app';
import { requestMessage as message } from '../../common/requestError';

/** Общий транспорт. Адрес задаёт описание раздела, а не условие внутри страницы. */
export default class CatalogApi {
  constructor(endpoint) {
    this.endpoint = endpoint;
  }
  url(id) {
    return app.forum.attribute('apiUrl') + '/roleplay/admin/' + this.endpoint + (id === undefined ? '' : '/' + id);
  }
  async list(params) {
    const response = await app.request({
      method: 'GET',
      url: this.url(),
      params,
      errorHandler: () => {}
    });
    return response.data;
  }
  async save(id, revision, fields) {
    await app.request({
      method: id === null ? 'POST' : 'PUT',
      url: this.url(id ?? undefined),
      body: {
        revision,
        fields
      },
      errorHandler: () => {}
    });
  }
  async toggle(id, revision, enabled) {
    await app.request({
      method: 'PATCH',
      url: this.url(id),
      body: {
        revision,
        enabled
      },
      errorHandler: () => {}
    });
  }
  async remove(id, revision) {
    await app.request({
      method: 'DELETE',
      url: this.url(id),
      body: {
        revision
      },
      errorHandler: () => {}
    });
  }
}

/** Ошибка отображается рядом с действием; подробности неожиданного сбоя остаются на сервере. */
export function requestMessage(error) {
  return message(error, 'Не удалось выполнить запрос. Проверь соединение и попробуй ещё раз.');
}
flarum.reg.add('maxcuso-roleplay', 'admin/catalog/CatalogApi', CatalogApi);