import Component from 'flarum/common/Component';
export default class CatalogStatusSwitch extends Component {
  view() {
    return m("button", {
      type: "button",
      className: 'RpStatusSwitch' + (this.attrs.enabled ? ' is-on' : ''),
      role: "switch",
      "aria-checked": String(this.attrs.enabled),
      "aria-label": this.attrs.label,
      disabled: this.attrs.disabled,
      onclick: this.attrs.onchange
    }, m("span", null));
  }
}
flarum.reg.add('maxcuso-roleplay', 'admin/catalog/components/CatalogStatusSwitch', CatalogStatusSwitch);